\title{Spectral Flatness of the Factoring Function\\
\large An exact zero-block theorem, a top-bit transmission law,\\
and the resolution of the low-bit anomaly}
\author{Aristotle}
\date{13 August 2026}

\begin{document}
\maketitle

\begin{abstract}
Let $N=pq$ be a semiprime with $k$-bit factors and let $f_j(N)$ denote bit $j$ of the smaller
factor. We study the Walsh (Fourier--$\mathrm{GF}(2)$) spectrum of $f_j$ as a function of the bits
of $N$, motivated by the question of whether any low-degree parity of the public value
approximates any bit of a secret factor. We prove three groups of results.
\emph{(i) An exact zero-block theorem.} Over the full odd support modulo $2^t$ --- all ordered
pairs $(p,q)$ of odd residues, with public value $N=pq\bmod 2^t$ --- for every bit index
$1\le j<t$ and every real-valued statistic $g$ of $N$, the signed correlation
$\sum_{p,q}(-1)^{p_j}g(pq \bmod 2^t)$ vanishes identically; the quantification over $g$ is
unrestricted, so this covers every $\mathrm{GF}(2)$ parity of every degree and every predictor
whatsoever. Consequently any Boolean predictor of $p_j$ reading only $N$ is correct on exactly
half the support, and in fact each fiber of the public value contains every odd residue exactly
once as a secret factor, so distinct public values induce identical distributions on the secret.
\emph{(ii) A top-bit transmission law.} For balanced factors $2^{k-1}\le p\le q<2^k$, the
implication $p_{k-2}=1\Rightarrow N_{2k-1}=1$ holds without exception; it is strictly one-sided,
the conditioning statistic is symmetric in $(p,q)$ and computable from $N$ alone, and the
covariance of the two events is strictly positive at every size with limit
$(2\log 2-1)/4=0.0965735\ldots$, equivalently a limiting correlation
$4\log 2-5/2=0.2725887\ldots$
\emph{(iii) A resolution of the empirical anomalies.} The only non-flat structure in exhaustive
low-degree scans is this symmetric magnitude family, whose measured strength $0.285$ at $k=14$
agrees with that constant; the previously unexplained low-bit correlation at small sizes
($+0.254$ at $k=8$, $+0.166$ at $k=10$) alternates in sign with the bit length and decays to
$-0.0064$ at $k=14$, below the noise level of the scan, identifying it as a finite-sample
fluctuation rather than an approximator. On the ordered
support $p<q$ --- the one place where the zero-block theorem provably fails --- exact computation
shows the maximising spectral coefficient is always the empty parity at the highest bit of $p$:
the residual defect is the order statistic itself.
\end{abstract}

\noindent\textbf{Keywords.} Walsh spectrum; Boolean Fourier analysis; integer factorization;
semiprimes; $\mathrm{GF}(2)$ parity; low-degree approximation; carry propagation; perfect secrecy.

\section{Introduction}

\subsection{The question}

Modern public-key cryptography rests on the presumed one-wayness of multiplication: the product
$N=pq$ of two large primes is public, the factors are secret, and no efficient factoring algorithm
is known. Unconditional hardness is far out of reach. What is within reach is the systematic
exclusion of specific attack families --- a \emph{barrier framework}, in which each theorem says
that some natural class of algorithms cannot extract secret information from the public value.

This paper treats the most elementary such class: low-degree $\mathrm{GF}(2)$ parities. Write the
public value in binary as $N=\sum_i N_i 2^i$ and the smaller factor as $p=\sum_j p_j 2^j$. For a
set $S$ of bit positions of $N$ the parity function is
\[
  \chi_S(N)=\bigoplus_{i\in S}N_i,\qquad \deg\chi_S=|S| .
\]
Does some parity of small degree predict some bit $p_j$ appreciably better than a coin? Any
learning procedure that begins by fitting a low-degree model over $\mathrm{GF}(2)$ is asking
precisely this question, and the Walsh spectrum answers it exhaustively.

\subsection{The empirical picture}

An exhaustive spectral census on exact $k$-bit prime semiprime supports (support sizes
$m=276,\,2850,\,32640,\,380628$ at $k=8,10,12,14$, degree-$\le 3$ scans at $k=14$, random-sign null
models calibrated per size) gives the following.

\begin{enumerate}
\item \textbf{Flatness.} At $k=14$, every information-bearing bit below the top $\approx 6$ has
maximum degree-$\le 3$ correlation at most $0.021$, against an all-parity noise level of $0.0101$
and a degree-$\le 3$ null maximum of $0.0065$.
\item \textbf{The one exception.} The correlations $\corr(p_{k-d},N_{2k-1})$ for $d=2,\dots,6$
take values of order $0.285$, $0.310$, $0.132$, $0.065$, $0.026$: a magnitude/carry family at the
top of the factor, symmetric in $(p,q)$ and computable from $N$ alone.
\item \textbf{A small-$k$ oddity.} $\corr(p_2,N_{2k-1})$ measured $0.254/0.166/0.013/0.006$ at
$k=8/10/12/14$.
\item \textbf{Low-half cubics.} $\corr(f_3,\chi_{\{1,2,3\}})$ decays from $0.203$ to $0.013$ and
$\corr(f_4,\chi_{\{1,3,4\}})$ from $0.145$ to $0.009$ across $k=8,\dots,14$.
\item \textbf{Controls.} Degree-$\le 3$ null maxima $0.074/0.0213/0.0065$ at $k=10/12/14$; the
constant bits $j=0$ and $j=k-1$ trivially correlate at $1.0$; the carry-out bit reproduces at
$0.51$ (linear) and $0.79$ (quadratic).
\end{enumerate}

The purpose of this paper is to replace measurements by theorems: to prove that the flat part is
exactly flat, that the non-flat part is exactly the magnitude family, and that items 3 and 4 are
finite-support fluctuations.

\section{The Walsh calculus and what ``flat'' means}

Throughout, functions are defined on the cube $\{0,1\}^n$.

\begin{definition}[Sign encoding]
For a Boolean value $b$ set $\sgn(b)=1$ if $b=0$ and $\sgn(b)=-1$ if $b=1$. Then $\sgn(b)^2=1$ and
$\sgn(a)\sgn(b)=1$ iff $a=b$.
\end{definition}

\begin{definition}[Walsh character]
For $S\subseteq\{0,\dots,n-1\}$ and $x\in\{0,1\}^n$, $\displaystyle
\chi_S(x)=\prod_{i\in S}\sgn(x_i)=(-1)^{\bigoplus_{i\in S}x_i}\in\{\pm1\}$.
\end{definition}

\begin{proposition}[Group law]
$\chi_S(x)\chi_T(x)=\chi_{S\triangle T}(x)$ for all $S,T,x$.
\end{proposition}
\begin{proof}
Split $S\cup T$ into $S\triangle T$ and $S\cap T$; coordinates in $S\cap T$ contribute
$\sgn(x_i)^2=1$.
\end{proof}

\begin{proposition}[Character sum]\label{prop:charsum}
$\sum_{x}\chi_S(x)=2^n$ if $S=\emptyset$ and $0$ otherwise.
\end{proposition}
\begin{proof}
Write $\chi_S(x)=\prod_i c_i(x_i)$ with $c_i=\sgn$ for $i\in S$ and $c_i\equiv 1$ otherwise, and
expand the cube sum as a product of one-coordinate sums; each coordinate of $S$ contributes
$\sgn(0)+\sgn(1)=0$.
\end{proof}

\begin{corollary}[Orthogonality]
$\sum_x \chi_S(x)\chi_T(x)=2^n\one[S=T]$.
\end{corollary}

\begin{proposition}[Dual orthogonality]\label{prop:dual}
$\sum_S \chi_S(x)\chi_S(y)=2^n\one[x=y]$, the sum over all $2^n$ subsets.
\end{proposition}
\begin{proof}
$\sum_S\prod_{i\in S}\sgn(x_i)\sgn(y_i)=\prod_i\bigl(1+\sgn(x_i)\sgn(y_i)\bigr)$, a product of
factors equal to $2$ when $x_i=y_i$ and $0$ otherwise.
\end{proof}

\begin{definition}
For $f:\{0,1\}^n\to\mathbb{R}$ put $\widehat{W}f(S)=\sum_x f(x)\chi_S(x)$ and
$\corr(f,S)=2^{-n}\widehat{W}f(S)$. Call $f$ a \emph{sign function} if $f(x)\in\{\pm1\}$ for all
$x$.
\end{definition}

\begin{theorem}[Parseval]\label{thm:parseval}
$\sum_S\widehat{W}f(S)^2=2^n\sum_x f(x)^2$. In particular, for a sign function,
$\sum_S\corr(f,S)^2=1$.
\end{theorem}
\begin{proof}
Expand each square as a double sum over $x,y$, interchange summation order, and collapse the
$S$-sum onto the diagonal by Proposition~\ref{prop:dual}.
\end{proof}

\begin{theorem}[Correlation is prediction advantage]\label{thm:dict}
Let $f$ be a sign function and $\agree(f,S)=\#\{x: f(x)=\chi_S(x)\}$. Then
$\agree(f,S)=2^{n}\bigl(1+\corr(f,S)\bigr)/2$.
\end{theorem}
\begin{proof}
Split $\widehat{W}f(S)$ into agreeing and disagreeing points, contributing $+1$ and $-1$
respectively: $\widehat Wf(S)=2\agree(f,S)-2^n$.
\end{proof}

\begin{corollary}[The $1/2$ barrier]
If $\corr(f,S)\le\varepsilon$ then $\chi_S$ predicts $f$ on at most a fraction
$(1+\varepsilon)/2$ of the cube; if $\corr(f,S)=0$ the rate is exactly $1/2$.
\end{corollary}

\begin{theorem}[Noise floor]
Every sign function admits some $S$ with $|\corr(f,S)|\ge 2^{-n/2}$.
\end{theorem}
\begin{proof}
Otherwise every squared coefficient is $<2^{-n}$; summing over $2^n$ subsets contradicts
Theorem~\ref{thm:parseval}.
\end{proof}

\begin{theorem}[Few heavy coefficients; spectral spreading]
For $\varepsilon>0$, $\#\{S:|\corr(f,S)|\ge\varepsilon\}\cdot\varepsilon^2\le 1$. Conversely, if
$|\corr(f,S)|\le\varepsilon$ for all $S$ then $\#\{S:\corr(f,S)\ne0\}\ge\varepsilon^{-2}$.
\end{theorem}
\begin{proof}
Both directions read the identity $\sum_S\corr(f,S)^2=1$: heavy coefficients each contribute at
least $\varepsilon^2$; and a total of $1$ must be assembled from contributions of at most
$\varepsilon^2$.
\end{proof}

\begin{theorem}[Low-degree mass bound]\label{thm:mass}
Let $\LowDeg(n,d)=\{S:|S|\le d\}$, of cardinality $\sum_{i\le d}\binom{n}{i}$. If
$|\corr(f,S)|\le\varepsilon$ for all $S\in\LowDeg(n,d)$ then
\[
  \sum_{|S|\le d}\corr(f,S)^2\le\varepsilon^2\sum_{i\le d}\binom{n}{i},
  \qquad
  \sum_{|S|>d}\corr(f,S)^2\ge 1-\varepsilon^2\sum_{i\le d}\binom{n}{i}.
\]
\end{theorem}

\begin{remark}[Numerical reading]
At $k=14$ the public value has $n=28$ bits, so a degree-$\le3$ scan touches
$1+28+378+3276=3683$ parities. With the observed $\varepsilon=0.021$, at most $2267<3683$
parities can be $\varepsilon$-heavy, and the low-degree mass is at most
$3683\cdot0.021^2\approx1.62$ --- consistent with, but not sufficient for, a conclusion about
mass escaping to high degree. This is why the next section proves an exact vanishing statement
rather than relying on a measured bound.
\end{remark}

\section{The zero-block theorem: exact flatness of the low block}

\begin{definition}[Odd support]
For $t\ge1$ let $U_t=\{x: 0\le x<2^t,\ x\text{ odd}\}$, the unit group of $\mathbb{Z}/2^t$, of size
$2^{t-1}$. The support is $U_t\times U_t$, of size $m=4^{t-1}$, and the public value of a pair is
$N=pq\bmod 2^t$. Write $\sigma_j(x)=(-1)^{x_j}$.
\end{definition}

\begin{lemma}[Balance of interior bits]\label{lem:balance}
For $1\le j<t$, $\sum_{x\in U_t}\sigma_j(x)=0$.
\end{lemma}
\begin{proof}
The map $\iota(x)=x\oplus 2^j$ is an involution of $U_t$: it preserves bit $0$ (as $j\ge1$), hence
oddness; it preserves the range (as $j<t$); and it is its own inverse. It flips bit $j$, so
$\sigma_j(\iota(x))=-\sigma_j(x)$: a sign-reversing involution forces the sum to vanish.
\end{proof}

\begin{lemma}[Simple transitivity]\label{lem:trans}
For $p\in U_t$ the map $q\mapsto pq\bmod2^t$ is a bijection of $U_t$ onto itself.
\end{lemma}
\begin{proof}
Odd $p$ is coprime to $2^t$, hence cancellable modulo $2^t$, so the map is injective; a product of
odd numbers is odd, so it maps $U_t$ into $U_t$; an injective self-map of a finite set is
bijective.
\end{proof}

\begin{theorem}[Zero-block theorem]\label{thm:zero}
Let $t\ge2$ and $1\le j<t$. For \emph{every} function $g:\mathbb{Z}/2^t\to\mathbb{R}$,
\[
  \sum_{p\in U_t}\ \sum_{q\in U_t}\ \sigma_j(p)\,g\bigl(pq\bmod 2^t\bigr)=0 .
\]
\end{theorem}
\begin{proof}
Fix $p$. By Lemma~\ref{lem:trans} the inner sum re-indexes as
$\sigma_j(p)\sum_{N\in U_t}g(N)$, whose second factor is independent of $p$. Summing over $p$ gives
$\bigl(\sum_p\sigma_j(p)\bigr)\bigl(\sum_N g(N)\bigr)$, and the first factor vanishes by
Lemma~\ref{lem:balance}.
\end{proof}

The scope of the quantifier is the point: $g$ is an arbitrary real function of the public value ---
every parity of arbitrary degree, every polynomial in the bits, every look-up table, every trained
model. All have correlation exactly $0$ with $p_j$.

\begin{corollary}[The measured spectrum vanishes]
Let $S$ be a set of bit positions with $\max S<t$ and let $\chi_S$ denote the parity of those bits
of the \emph{integer} product $pq$. Then $\sum_{p,q\in U_t}\sigma_j(p)\chi_S(pq)=0$ for all
$1\le j<t$.
\end{corollary}
\begin{proof}
Bits below $t$ of $pq$ agree with the corresponding bits of $pq\bmod2^t$; apply
Theorem~\ref{thm:zero} with $g=\chi_S$.
\end{proof}

\begin{theorem}[Exact $1/2$ barrier]\label{thm:barrier}
Let $1\le j<t$ and let $h:\mathbb{Z}/2^t\to\{0,1\}$ be arbitrary. Then
\[
  \#\{(p,q)\in U_t^2 : h(pq\bmod2^t)=p_j\}
  =\#\{(p,q)\in U_t^2 : h(pq\bmod2^t)\ne p_j\}.
\]
\end{theorem}
\begin{proof}
Apply Theorem~\ref{thm:zero} with $g(N)=\sgn(h(N))$. The summand $\sigma_j(p)\sgn(h(N))$ equals
$+1$ exactly on agreeing pairs and $-1$ exactly on disagreeing pairs, so a vanishing
$\pm1$-valued sum forces equality of the two counts.
\end{proof}

\begin{definition}
For $N\in U_t$ let $\Fib(N)=\{(p,q)\in U_t^2 : pq\equiv N \pmod {2^t}\}$.
\end{definition}

\begin{lemma}\label{lem:fiber}
For every $N,a\in U_t$ there is exactly one pair in $\Fib(N)$ with first coordinate $a$, namely
$(a,a^{-1}N\bmod 2^t)$. Hence $|\Fib(N)|=2^{t-1}$ and $(p,q)\mapsto p$ is a bijection
$\Fib(N)\to U_t$.
\end{lemma}

\begin{theorem}[Perfect secrecy of the low block]
For every predicate $P$ on $U_t$ and all $N,N'\in U_t$,
\[
 \#\{(p,q)\in\Fib(N):P(p)\}=\#\{a\in U_t : P(a)\}=\#\{(p,q)\in\Fib(N'):P(p)\}.
\]
In particular, for $1\le j<t$ bit $j$ of the secret factor is $0$ on exactly half of each fiber,
and any $h$ producing a single candidate for the secret low block satisfies
$\#\{(p,q)\in\Fib(N): p=h(N)\}\le1$: success probability exactly $2^{-(t-1)}$, the blind-guess
rate.
\end{theorem}
\begin{proof}
Immediate from Lemma~\ref{lem:fiber}, with Lemma~\ref{lem:balance} for the bit statement.
\end{proof}

\begin{theorem}[The mechanism, abstractly]
Let $G$ be a finite group and $u,g:G\to\mathbb{R}$ with $\sum_{a}u(a)=0$. Then
$\sum_{a}\sum_{b}u(a)g(ab)=0$.
\end{theorem}
\begin{proof}
For fixed $a$, right translation $b\mapsto ab$ is a bijection, so $\sum_b g(ab)=\sum_c g(c)$
independently of $a$; factor and use $\sum_a u(a)=0$.
\end{proof}

Theorem~\ref{thm:zero} is the case $G=(\mathbb{Z}/2^t)^\times$, $u=\sigma_j$: what kills the
correlation is the simple transitivity of the regular representation, not any property of primes.
The arithmetic input is confined to Lemma~\ref{lem:balance}; for $j=0$ the statistic is constant
(all units are odd), which is why the census reports a trivial correlation of $1.0$ there.

\section{The top-bit law: the unique non-flat family}

\begin{definition}[Balanced support]
For $k\ge2$ let $\mathcal{B}_k=\{(p,q): 2^{k-1}\le p\le q<2^k\}$. For $(p,q)\in\mathcal{B}_k$ we
have $2^{2k-2}\le N=pq<2^{2k}$, so $N_{2k-1}=\one[N\ge2^{2k-1}]$ is the carry-out indicator.
\end{definition}

\begin{lemma}\label{lem:three}
If $2^{k-1}\le p$ and $p_{k-2}=1$ then $p\ge 3\cdot2^{k-2}$.
\end{lemma}
\begin{proof}
$p\ge2^{k-1}$ gives $\lfloor p/2^{k-2}\rfloor\ge2$, and $p_{k-2}=1$ says this quotient is odd, so
it is $\ge3$.
\end{proof}

\begin{theorem}[Top-bit transmission law]\label{thm:top}
Let $(p,q)\in\mathcal{B}_k$. If $p_{k-2}=1$ then $N=pq\ge2^{2k-1}$, i.e.\ $N_{2k-1}=1$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:three}, $p\ge3\cdot2^{k-2}$, and $q\ge p$ gives the same for $q$. Hence
$N\ge9\cdot2^{2k-4}>8\cdot2^{2k-4}=2^{2k-1}$. Since $N<2^{2k}$, the inequality $N\ge2^{2k-1}$ is
exactly the statement that bit $2k-1$ of $N$ is set.
\end{proof}

\begin{corollary}
If the product does not carry into its top bit ($N<2^{2k-1}$) then necessarily $p_{k-2}=0$.
\end{corollary}

\begin{proposition}[Symmetry]
For all $p,q,m$, bit $m$ of $pq$ equals bit $m$ of $qp$. The conditioning statistic $N_{2k-1}$ is
therefore a symmetric function of the factor pair, computable from $N$ alone: it distinguishes
size, never which factor is which.
\end{proposition}

\begin{proposition}[Strict one-sidedness]
The converse of Theorem~\ref{thm:top} fails already at $k=5$: $17\cdot31=527$ and $29\cdot31=899$
both lie in $\mathcal{B}_5$ with $N_9=1$, yet the second-highest bit of the smaller factor is $0$
for $p=17$ and $1$ for $p=29$; likewise $17\cdot31=527$ and $19\cdot29=551$ agree in $N_9$ and
differ in bit $1$ of the smaller factor. Knowledge of $N_{2k-1}$ determines neither $p_{k-2}$ nor
any low bit of $p$.
\end{proposition}

\begin{definition}
Over the uniform measure on $\mathcal{B}_k$ let $A=\{p_{k-2}=1\}$, $B=\{N_{2k-1}=1\}$ and
$\mathrm{cov}_k=\Prob(A\cap B)-\Prob(A)\Prob(B)$.
\end{definition}

\begin{theorem}[The top-bit family is non-flat at every size]
$\mathrm{cov}_k>0$ for every $k\ge2$.
\end{theorem}
\begin{proof}
Theorem~\ref{thm:top} gives $A\subseteq B$, so $\mathrm{cov}_k=\Prob(A)\bigl(1-\Prob(B)\bigr)$. Now
$A\ne\emptyset$, since $(3\cdot2^{k-2},3\cdot2^{k-2})\in\mathcal{B}_k$ has $p_{k-2}=1$; and
$B\ne\mathcal{B}_k$, since $(2^{k-1},2^{k-1})\in\mathcal{B}_k$ has $N=2^{2k-2}<2^{2k-1}$. Both
factors are strictly positive.
\end{proof}

The contrast with the previous section is the substance of the verdict: on the low block the
correlation is exactly zero at every size; in the top-bit family it is strictly positive at every
size.

\begin{proposition}[Limiting constant]
$\displaystyle\lim_{k\to\infty}\mathrm{cov}_k=\frac{2\log2-1}{4}=0.0965735\ldots$
\end{proposition}
\begin{proof}[Sketch]
Rescale $p=2^{k-1}x$, $q=2^{k-1}y$; the support becomes
$\mathcal{S}=\{(x,y)\in[1,2]^2:x\le y\}$ of area $1/2$, and the uniform measures converge weakly.
The event $A$ becomes $\{x\ge3/2\}\cap\mathcal{S}$ of area $\int_{3/2}^2(2-x)\,dx=1/8$, hence
$\Prob(A)=1/4$. The complement of $B=\{xy\ge2\}\cap\mathcal{S}$ inside $\mathcal{S}$ is
$\{1\le x\le\sqrt2,\ x\le y<2/x\}$, of area $\int_1^{\sqrt2}(2/x-x)\,dx=\log2-\tfrac12$; hence
$\mathrm{area}(B)=1-\log2$ and $\Prob(B)=2(1-\log2)=0.61371\ldots$. The inclusion $A\subseteq B$
survives in the limit (if $x\ge3/2$ and $y\ge x$ then $xy\ge9/4>2$), so
$\mathrm{cov}_\infty=\Prob(A)(1-\Prob(B))=(2\log2-1)/4$.
\end{proof}

